    20→package org.apache.druid.indexing.overlord.sampler;
    21→
    22→import com.fasterxml.jackson.annotation.JsonCreator;
    23→import com.fasterxml.jackson.annotation.JsonProperty;
    24→import com.google.common.base.Preconditions;
    25→
    26→public class SamplerConfig
    27→{
    28→  private static final int DEFAULT_NUM_ROWS = 200;
    29→  private static final int MAX_NUM_ROWS = 5000;
    30→  private static final int DEFAULT_TIMEOUT_MS = 10000;
    31→
    32→  private final int numRows;
    33→  private final int timeoutMs;
    34→
    35→  @JsonCreator
    36→  public SamplerConfig(
    37→      @JsonProperty("numRows") Integer numRows,
    38→      @JsonProperty("timeoutMs") Integer timeoutMs
    39→  )
    40→  {
    41→    this.numRows = numRows != null ? numRows : DEFAULT_NUM_ROWS;
    42→    this.timeoutMs = timeoutMs != null ? timeoutMs : DEFAULT_TIMEOUT_MS;
    43→
    44→    Preconditions.checkArgument(this.numRows <= MAX_NUM_ROWS, "numRows must be <= %s", MAX_NUM_ROWS);
    45→  }
    46→
    47→  /**
    48→   * The maximum number of rows to return in a response. The actual number of returned rows may be less if:
    49→   *   - The sampled source contains less data.
    50→   *   - {@link SamplerConfig#timeoutMs} elapses before this value is reached.
    51→   *   - {@link org.apache.druid.segment.indexing.granularity.GranularitySpec#isRollup()} is true and input rows get
    52→   *     rolled-up into fewer indexed rows.
    53→   *
    54→   * @return maximum number of sampled rows to return
    55→   */
    56→  public int getNumRows()
    57→  {
    58→    return numRows;
    59→  }
    60→
    61→  /**
    62→   * Time to wait in milliseconds before closing the sampler and returning the data which has already been read.
    63→   * Particularly useful for handling streaming input sources where the rate of data is unknown, to prevent the sampler
    64→   * from taking an excessively long time trying to reach {@link SamplerConfig#numRows}.
    65→   *
    66→   * @return timeout in milliseconds
    67→   */
    68→  public int getTimeoutMs()
    69→  {
    70→    return timeoutMs;
    71→  }
    72→
    73→  public static SamplerConfig empty()
    74→  {
    75→    return new SamplerConfig(null, null);
    76→  }
    77→}
