    56→{
    57→  private static final Logger log = new Logger(DataSchema.class);
    58→  private static final Pattern INVALIDCHARS = Pattern.compile("(?s).*[^\\S ].*");
    59→  private final String dataSource;
    60→  private final AggregatorFactory[] aggregators;
    61→  private final GranularitySpec granularitySpec;
    62→  private final TransformSpec transformSpec;
    63→  private final Map<String, Object> parserMap;
