    69→
    70→  // This is used for backward compatibility
    71→  private InputRowParser inputRowParser;
    72→
    73→  @JsonCreator
    74→  public DataSchema(
    75→      @JsonProperty("dataSource") String dataSource,
    76→      @JsonProperty("timestampSpec") @Nullable TimestampSpec timestampSpec, // can be null in old task spec
    77→      @JsonProperty("dimensionsSpec") @Nullable DimensionsSpec dimensionsSpec, // can be null in old task spec
    78→      @JsonProperty("metricsSpec") AggregatorFactory[] aggregators,
    79→      @JsonProperty("granularitySpec") GranularitySpec granularitySpec,
    80→      @JsonProperty("transformSpec") TransformSpec transformSpec,
    81→      @Deprecated @JsonProperty("parser") @Nullable Map<String, Object> parserMap,
    82→      @JacksonInject ObjectMapper objectMapper
    83→  )
    84→  {
    85→    validateDatasourceName(dataSource);
    86→    this.dataSource = dataSource;
    87→
    88→    this.timestampSpec = timestampSpec;
    89→    this.aggregators = aggregators == null ? new AggregatorFactory[]{} : aggregators;
    90→    this.dimensionsSpec = dimensionsSpec == null
    91→                          ? null
    92→                          : computeDimensionsSpec(
    93→                              Preconditions.checkNotNull(timestampSpec, "timestampSpec"),
    94→                              dimensionsSpec,
    95→                              this.aggregators
    96→                          );
    97→
    98→    if (granularitySpec == null) {
    99→      log.warn("No granularitySpec has been specified. Using UniformGranularitySpec as default.");
   100→      this.granularitySpec = new UniformGranularitySpec(null, null, null);
   101→    } else {
   102→      this.granularitySpec = granularitySpec;
   103→    }
   104→    this.transformSpec = transformSpec == null ? TransformSpec.NONE : transformSpec;
   105→    this.parserMap = parserMap;
   106→    this.objectMapper = objectMapper;
   107→
   108→    if (aggregators != null && aggregators.length != 0) {
   109→      // validate for no duplication
   110→      Set<String> names = new HashSet<>();
   111→      for (AggregatorFactory factory : aggregators) {
   112→        if (!names.add(factory.getName())) {
   113→          throw new IAE("duplicate aggregators found with name [%s].", factory.getName());
   114→        }
   115→      }
   116→    } else if (this.granularitySpec.isRollup()) {
   117→      log.warn("No metricsSpec has been specified. Are you sure this is what you want?");
   118→    }
   119→  }
