   212→  public DimensionsSpec getDimensionsSpec()
   213→  {
   214→    if (dimensionsSpec == null) {
   215→      dimensionsSpec = computeDimensionsSpec(
   216→          getTimestampSpec(),
   217→          Preconditions.checkNotNull(getParser(), "inputRowParser").getParseSpec().getDimensionsSpec(),
   218→          aggregators
   219→      );
   220→    }
   221→    return dimensionsSpec;
   222→  }
   223→
   224→  @JsonProperty("metricsSpec")
