   238→  {
   239→    return transformSpec;
   240→  }
   241→
   242→  @Deprecated
   243→  @JsonProperty("parser")
   244→  @Nullable
   245→  @JsonInclude(Include.NON_NULL)
   246→  public Map<String, Object> getParserMap()
   247→  {
   248→    return parserMap;
   249→  }
   250→
   251→  @Nullable
   252→  public InputRowParser getParser()
   253→  {
   254→    if (inputRowParser == null) {
   255→      if (parserMap == null) {
   256→        return null;
   257→      }
   258→      //noinspection unchecked
   259→      inputRowParser = transformSpec.decorate(objectMapper.convertValue(this.parserMap, InputRowParser.class));
   260→      ParseSpec parseSpec = inputRowParser.getParseSpec();
   261→      parseSpec = parseSpec.withDimensionsSpec(
   262→          computeDimensionsSpec(parseSpec.getTimestampSpec(), parseSpec.getDimensionsSpec(), aggregators)
   263→      );
   264→      if (timestampSpec != null) {
   265→        parseSpec = parseSpec.withTimestampSpec(timestampSpec);
   266→      }
   267→      if (dimensionsSpec != null) {
   268→        parseSpec = parseSpec.withDimensionsSpec(dimensionsSpec);
   269→      }
   270→      inputRowParser = inputRowParser.withParseSpec(parseSpec);
   271→    }
   272→    return inputRowParser;
   273→  }
