    31→/**
    32→ */
    33→@JsonTypeInfo(use = JsonTypeInfo.Id.NAME, property = "type")
    34→@JsonSubTypes(value = {
    35→    @JsonSubTypes.Type(name = "and", value = AndDimFilter.class),
    36→    @JsonSubTypes.Type(name = "or", value = OrDimFilter.class),
    37→    @JsonSubTypes.Type(name = "not", value = NotDimFilter.class),
    38→    @JsonSubTypes.Type(name = "selector", value = SelectorDimFilter.class),
    39→    @JsonSubTypes.Type(name = "columnComparison", value = ColumnComparisonDimFilter.class),
    40→    @JsonSubTypes.Type(name = "extraction", value = ExtractionDimFilter.class),
    41→    @JsonSubTypes.Type(name = "regex", value = RegexDimFilter.class),
