    41→/**
    42→ *
    43→ */
    44→public class Transformer
    45→{
    46→  private final Map<String, RowFunction> transforms = new HashMap<>();
    47→  private final ThreadLocal<Row> rowSupplierForValueMatcher = new ThreadLocal<>();
    48→  private final ValueMatcher valueMatcher;
    49→
    50→  Transformer(final TransformSpec transformSpec)
    51→  {
    52→    for (final Transform transform : transformSpec.getTransforms()) {
    53→      transforms.put(transform.getName(), transform.getRowFunction());
    54→    }
    55→
    56→    if (transformSpec.getFilter() != null) {
    57→      valueMatcher = transformSpec.getFilter().toFilter()
    58→                                  .makeMatcher(
    59→                                      RowBasedColumnSelectorFactory.create(
    60→                                          RowAdapters.standardRow(),
    61→                                          rowSupplierForValueMatcher::get,
    62→                                          RowSignature.empty(),
    63→                                          false
    64→                                      )
    65→                                  );
    66→    } else {
    67→      valueMatcher = null;
    68→    }
    69→  }
    70→
    71→  /**
    72→   * Transforms an input row, or returns null if the row should be filtered out.
    73→   *
    74→   * @param row the input row
    75→   */
    76→  @Nullable
    77→  public InputRow transform(@Nullable final InputRow row)
    78→  {
    79→    if (row == null) {
    80→      return null;
    81→    }
    82→
    83→    final InputRow transformedRow;
    84→
    85→    if (transforms.isEmpty()) {
    86→      transformedRow = row;
    87→    } else {
    88→      transformedRow = new TransformedInputRow(row, transforms);
    89→    }
    90→
    91→    if (valueMatcher != null) {
    92→      rowSupplierForValueMatcher.set(transformedRow);
    93→      if (!valueMatcher.matches()) {
    94→        return null;
    95→      }
    96→    }
    97→
    98→    return transformedRow;
    99→  }
